        record = records[0]
        self.assertEqual(record["component"]["name"], "app")
        self.assertFalse(record["direct"])
        # flask is absent from the returned list but still propagates the hit.
        self.assertEqual(
            [node["name"] for node in record["path"]], ["app", "flask"]
        )

