                    key = (record["source"], record["id"], normalized)
                    groups.setdefault(key, {})[component_id] = {
                        "severity": record["severity"],
                        "severity_basis": (
                            "default"
                            if record["severity_default"]
                            else "declared"
                        ),
                        "matched_conditions": matched_conditions,
                    }
    return groups

